using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace LanScope;
public sealed class DisplaySettingsWindow : Window
{
    public DisplaySettingsWindow(UiLayoutOptions initial,Action<UiLayoutOptions> changed,bool admin,Action<string,string> changePassword,string guestId,Action<string,string> changeGuest)
    {
        Title="DRAS · 설정";Width=Math.Min(760,SystemParameters.WorkArea.Width);Height=Math.Min(860,SystemParameters.WorkArea.Height);WindowStartupLocation=WindowStartupLocation.CenterOwner;MinWidth=460;MinHeight=460;ResizeMode=ResizeMode.CanResizeWithGrip;Background=new SolidColorBrush(Color.FromRgb(243,246,250));FontSize=13;
        var tabs=new TabControl{Margin=new Thickness(20)};Content=tabs;var value=initial;var refresh=new List<Action<UiLayoutOptions>>();bool updating=false;
        StackPanel Tab(string name,string explanation){var p=new StackPanel{Margin=new Thickness(22)};p.Children.Add(new TextBlock{Text=explanation,TextWrapping=TextWrapping.Wrap,Foreground=Brushes.SlateGray});tabs.Items.Add(new TabItem{Header=name,ToolTip=explanation,Content=new ScrollViewer{Content=p,VerticalScrollBarVisibility=ScrollBarVisibility.Auto}});return p;}
        var fonts=Tab("글자 크기","영역별로 글자 크기를 조절합니다. 변경 사항은 즉시 적용됩니다.");var layout=Tab("배치·입력란","목록의 폭과 시험 기록명 입력란 크기를 조절합니다. 시험 기록명 입력란 모서리도 끌어 크기를 바꿀 수 있습니다.");
        void Add(StackPanel panel,string label,int min,int max,Func<UiLayoutOptions,int> get,Func<UiLayoutOptions,int,UiLayoutOptions> set){var text=new TextBlock{Margin=new Thickness(0,18,0,8)};var slider=new Slider{Minimum=min,Maximum=max,Value=get(value),TickFrequency=1,IsSnapToTickEnabled=true,ToolTip=label+" 값을 조절합니다. 설정은 이 Windows 사용자에게 저장됩니다."};panel.Children.Add(text);panel.Children.Add(slider);text.Text=label+" · "+get(value);slider.ValueChanged+=(_,e)=>{text.Text=label+" · "+(int)e.NewValue;if(!updating){value=set(value,(int)e.NewValue);changed(value);}};refresh.Add(v=>{slider.Value=get(v);text.Text=label+" · "+get(v);});}
        Add(fonts,"본문",12,20,v=>v.Body,(v,n)=>v with{Body=n});Add(fonts,"메뉴",12,20,v=>v.Menu,(v,n)=>v with{Menu=n});Add(fonts,"표 내용",10,20,v=>v.Table,(v,n)=>v with{Table=n});Add(fonts,"표 제목",11,22,v=>v.TableHeader,(v,n)=>v with{TableHeader=n});Add(fonts,"화면 제목",20,36,v=>v.Title,(v,n)=>v with{Title=n});Add(fonts,"시험 기록명",12,36,v=>v.TestNameFont,(v,n)=>v with{TestNameFont=n});
        Add(layout,"ICD 목록 너비 (px)",180,500,v=>v.ProfileWidth,(v,n)=>v with{ProfileWidth=n});Add(layout,"NIC 목록 비율 (%)",30,75,v=>v.NicPercent,(v,n)=>v with{NicPercent=n});Add(layout,"기록명 입력란 너비 (px)",240,900,v=>v.TestNameWidth,(v,n)=>v with{TestNameWidth=n});Add(layout,"기록명 입력란 높이 (px)",56,180,v=>v.TestNameHeight,(v,n)=>v with{TestNameHeight=n});
        Add(layout,"ICD 필드 표 높이 (px)",200,1200,v=>v.IcdTableHeight,(v,n)=>v with{IcdTableHeight=n});
        layout.Children.Add(new TextBlock{Text="메인 창 크기 (화면 작업 영역 이내로 적용)",FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,24,0,12)});
        TextBox Number(string label,int number){layout.Children.Add(new TextBlock{Text=label,Margin=new Thickness(0,12,0,6)});var box=new TextBox{Text=number.ToString(),Padding=new Thickness(10),ToolTip=label+"를 숫자로 입력하세요."};layout.Children.Add(box);return box;}
        var width=Number("너비 (1000~3840 px)",value.WindowWidth);var height=Number("높이 (680~2160 px)",value.WindowHeight);var maximized=new CheckBox{Content="메인 창 최대화",IsChecked=value.Maximized,Margin=new Thickness(0,16,0,10)};layout.Children.Add(maximized);
        var sizeStatus=new TextBlock{TextWrapping=TextWrapping.Wrap};var sizeSave=new Button{Content="창 크기 적용·저장",Padding=new Thickness(12),ToolTip="입력한 창 크기와 최대화 상태를 적용하고 저장합니다. 픽셀 값은 WPF 논리 픽셀 기준입니다."};layout.Children.Add(sizeSave);layout.Children.Add(sizeStatus);
        sizeSave.Click+=(_,_)=>{try{if(!int.TryParse(width.Text,out int w)||!int.TryParse(height.Text,out int h))throw new ArgumentException("창 크기는 정수로 입력하세요.");var candidate=value with{WindowWidth=w,WindowHeight=h,Maximized=maximized.IsChecked==true};candidate.Validate();changed(candidate);value=candidate;sizeStatus.Text="창 크기 저장 완료";}catch(Exception e){sizeStatus.Text=e.Message;}};
        refresh.Add(v=>{width.Text=v.WindowWidth.ToString();height.Text=v.WindowHeight.ToString();maximized.IsChecked=v.Maximized;});
        foreach(var panel in new[]{fonts,layout}){var reset=new Button{Content="기본 설정 복원",Margin=new Thickness(0,24,0,0),Padding=new Thickness(12),ToolTip="글자와 입력란 배치를 기본값으로 되돌립니다. ICD와 기록 폴더는 변경하지 않습니다."};panel.Children.Add(reset);reset.Click+=(_,_)=>{value=new();updating=true;foreach(var f in refresh)f(value);updating=false;changed(value);};}
        if(admin){var account=Tab("계정·보안","관리자·게스트 로그인 정보를 관리합니다. 게스트 ID/비밀번호 변경 후에도 기존 ICD 변환 허용 목록은 유지됩니다.");PasswordBox Password(string label){account.Children.Add(new TextBlock{Text=label,Margin=new Thickness(0,22,0,8)});var box=new PasswordBox{Padding=new Thickness(12),ToolTip=label+"를 입력합니다."};account.Children.Add(box);return box;}PasswordBox current=Password("현재 비밀번호"),next=Password("새 비밀번호 (8~128자)"),confirm=Password("새 비밀번호 확인");var status=new TextBlock{TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,16,0,0)};var save=new Button{Content="관리자 비밀번호 변경",Margin=new Thickness(0,24,0,0),Padding=new Thickness(14),ToolTip="현재 비밀번호를 검증하고 새 비밀번호로 로그인하도록 저장합니다. 기존 암호화 ICD는 계속 읽을 수 있습니다."};account.Children.Add(save);account.Children.Add(status);save.Click+=(_,_)=>{try{if(next.Password!=confirm.Password)throw new ArgumentException("새 비밀번호와 확인이 다릅니다.");changePassword(current.Password,next.Password);status.Text="비밀번호 변경 완료. 다음 로그인부터 새 비밀번호를 사용하세요.";}catch(Exception e){status.Text=e.Message;}finally{current.Clear();next.Clear();confirm.Clear();}};
            account.Children.Add(new Separator{Margin=new Thickness(0,28,0,18)});account.Children.Add(new TextBlock{Text="게스트 ID·비밀번호 관리",FontSize=17,FontWeight=FontWeights.SemiBold});account.Children.Add(new TextBlock{Text="관리자만 변경할 수 있습니다. 새 비밀번호는 표시하거나 다시 불러오지 않습니다. 다음 게스트 로그인부터 적용됩니다.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,10,0,0),Foreground=Brushes.SlateGray});
            account.Children.Add(new TextBlock{Text="게스트 ID (영문·숫자·_.-)",Margin=new Thickness(0,18,0,8)});var guestName=new TextBox{Text=guestId,Padding=new Thickness(12)};account.Children.Add(guestName);var guestPassword=Password("게스트 새 비밀번호 (8~128자)");var guestConfirm=Password("게스트 새 비밀번호 확인");var guestStatus=new TextBlock{TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,12,0,0)};var guestSave=new Button{Content="게스트 계정 저장",Margin=new Thickness(0,20,0,0),Padding=new Thickness(14),ToolTip="게스트 ID와 새 비밀번호를 저장하고 기존 기록·변환 권한을 유지합니다. 관리자만 가능합니다."};account.Children.Add(guestSave);account.Children.Add(guestStatus);
            guestSave.Click+=(_,_)=>{try{if(guestPassword.Password!=guestConfirm.Password)throw new ArgumentException("게스트 비밀번호 확인이 다릅니다.");changeGuest(guestName.Text,guestPassword.Password);guestStatus.Text="게스트 계정 변경 완료 · 다음 로그인부터 적용";}catch(Exception e){guestStatus.Text=e.Message;}finally{guestPassword.Clear();guestConfirm.Clear();}};
        }
    }
}
